1	// Every IPC call returns { ok, data | error }; unwrap it into a promise.
2	export const isDemo =
3	  new URLSearchParams(window.location.search).get("demo") === "1";
4	let demoBridgePromise;
5	
6	async function getBridge() {
7	  if (!isDemo) return window.benana;
8	  demoBridgePromise ||= import("./demo/bridge.js").then(
9	    (module) => module.demoBridge,
10	  );
11	  return demoBridgePromise;
12	}
13	
14	export function hasDesktopBridge() {
15	  return Boolean(window.benana?.invoke);
16	}
17	
18	export async function call(channel, payload) {
19	  const bridge = await getBridge();
20	  if (!bridge?.invoke) throw new Error("Benana needs the desktop runtime.");
21	  const res = await bridge.invoke(channel, payload);
22	  if (!res?.ok) throw new Error(res?.error || `${channel} failed`);
23	  return res.data;
24	}
25	
26	export const on = (channel, fn) => {
27	  if (!isDemo) return window.benana?.on?.(channel, fn) || (() => {});
28	  let off;
29	  getBridge().then((bridge) => {
30	    off = bridge.on(channel, fn);
31	  });
32	  return () => off?.();
33	};
