35	export function ago(ts) {
36	  if (!ts) return "";
37	  const s = Math.round((Date.now() - ts) / 1000);
38	  if (s < 60) return `${s}s`;
39	  if (s < 3600) return `${Math.round(s / 60)}m`;
40	  if (s < 86400) return `${Math.round(s / 3600)}h`;
41	  return `${Math.round(s / 86400)}d`;
42	}
