5	const base = () =>
6	  (env("NEATLOGS_REGION") === "eu"
7	    ? "https://eu.app.neatlogs.com"
8	    : "https://app.neatlogs.com") + "/api/v1/public";
9	const configured = () =>
10	  Boolean(env("NEATLOGS_API_KEY") && env("NEATLOGS_PROJECT_ID"));
