12	async function api(p, init = {}) {
13	  const timeoutMs = init.timeoutMs || 15000;
14	  const request = { ...init };
15	  delete request.timeoutMs;
16	  const res = await fetch(`${base()}${p}`, {
17	    ...request,
18	    signal: request.signal || AbortSignal.timeout(timeoutMs),
19	    headers: {
20	      Authorization: `Bearer ${env("NEATLOGS_API_KEY")}`,
21	      "x-project-id": env("NEATLOGS_PROJECT_ID"),
22	      "Content-Type": "application/json",
23	      ...(request.headers || {}),
24	    },
25	  });
26	  if (!res.ok) throw new Error(`Neatlogs ${p}: ${res.status}`);
27	  const j = await res.json();
28	  return j.data ?? j;
29	}
