37	async function searchTraces(query) {
38	  if (!configured()) return [];
39	  return api("/search/traces", {
40	    method: "POST",
41	    body: JSON.stringify({ query }),
42	  });
43	}
44	
45	function traceItems(value) {
46	  return Array.isArray(value)
47	    ? value
48	    : value?.traces || value?.spans || value?.items || value?.results || [];
49	}
