51	async function evidence(run, deps = {}) {
52	  if (!configured())
53	    return {
54	      source: "neatlogs",
55	      configured: false,
56	      matched: false,
57	      traces: [],
58	      error: "Set NEATLOGS_API_KEY and NEATLOGS_PROJECT_ID to link traces.",
59	    };
60	  if (!run.sessionId)
61	    return {
62	      source: "neatlogs",
63	      configured: true,
64	      matched: false,
65	      traces: [],
66	      matchReason:
67	        "The agent did not report a session identifier, so Benana cannot attribute a trace.",
68	    };
69	  const request = deps.api || api;
70	  try {
71	    const listed = traceItems(
72	      await request(
73	        `/traces?limit=20&sessionId=${encodeURIComponent(run.sessionId)}`,
74	      ),
75	    );
76	    const exact = listed.filter(
77	      (trace) =>
78	        String(trace.sessionId || trace.session_id || "") ===
79	        String(run.sessionId),
80	    );
81	    const traces = [];
82	    for (const trace of exact) {
83	      const id = trace.traceId || trace.trace_id || trace.id;
84	      let spans = [];
85	      let spansError;
86	      if (id) {
87	        try {
88	          spans = traceItems(
89	            await request(`/traces/${encodeURIComponent(id)}/spans?limit=50`),
90	          );
91	        } catch (error) {
92	          spansError = error.message;
93	        }
94	      }
95	      traces.push({ ...trace, spans, ...(spansError ? { spansError } : {}), raw: { trace, spans } });
96	    }
97	    return {
98	      source: "neatlogs",
99	      configured: true,
100	      matched: traces.length > 0,
101	      traces,
102	      matchReason: traces.length
103	        ? `Matched exact agent session ${run.sessionId}.`
104	        : `No trace matched exact agent session ${run.sessionId}.`,
105	    };
106	  } catch (error) {
107	    return {
108	      source: "neatlogs",
109	      configured: true,
110	      matched: false,
111	      traces: [],
112	      error: error.message,
113	    };
114	  }
115	}
