            {p.key === "build" && running && <i className="rail-live" />}
          </button>
        ))}
        {hasDesktopBridge() && (
          <button className="rail-item rail-foot" onClick={onOpenWorkspace}>
            <svg viewBox="0 0 24 24" aria-hidden="true">{ICONS.workspace}</svg>
            <span>Repo</span>
          </button>
        )}
      </nav>

      <div className="studio-body">
        <header className="studio-top">
          <div>
            <h1>{current.title}</h1>
            <p>{current.sub}</p>
          </div>
          <div className="top-status">
            <span className={`status-dot ${game?.server || "stopped"}`} />
            <span>{game?.server === "running" ? "Server running" : game?.server === "starting" ? "Server starting" : "Server stopped"}</span>
            <span className="sep" />
            <span className={`status-dot ${game?.bot === "online" ? "running" : "offline"}`} />
            <span>{game?.bot === "online" ? "Bot in game" : "Bot offline"}</span>
            {game?.mock && <span className="tag mock">Mock runtime</span>}
          </div>
        </header>
        {error && <div className="studio-error page-error">{error}</div>}

        {page === "build" && (
          <BuildPage mods={mods} mod={mod} setSelectedId={setSelectedId} lessons={lessons} onSeeMods={() => setPage("mods")} />
        )}
        {page === "mods" && <ModsPage mods={mods} mod={mod} setSelectedId={setSelectedId} onBuild={() => setPage("build")} />}
        {page === "insights" && <InsightsPage mods={mods} lessons={lessons} />}
        {page === "neatlogs" && <NeatlogsPage mods={mods} onOpenMod={(id) => { setSelectedId(id); setPage("mods"); }} />}
        {page === "entire" && <EntirePage mods={mods} setSelectedId={setSelectedId} />}
      </div>
    </div>
  );
}

import React from "react";
import { call, on, ago } from "../../api.js";
import GamePane from "../game/GamePane.jsx";
import { AttemptTimeline, Empty, PHASES, PartnerStatus, Pill, PlanChecks, ROLE, phaseIndex, shortSha } from "./shared.jsx";

const EXAMPLES = [
  "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.",
  "Arrows that explode on impact without breaking blocks, with a 5 second cooldown per player.",
  "Right-clicking with a blaze rod shoots a fireball where you look.",
];

export default function BuildPage({ mods, mod, setSelectedId, lessons, onSeeMods }) {
  const [prompt, setPrompt] = React.useState("");
  const [seed, setSeed] = React.useState(false);
  const [busy, setBusy] = React.useState(false);
  const [error, setError] = React.useState("");
  const [feed, setFeed] = React.useState([]);
  const selectedRef = React.useRef(null);
  selectedRef.current = mod?.id ?? null;
  const running = mods.some((m) => m.running);

  React.useEffect(() => {
    const off = on("studio:feed", ({ modId, item }) => {
      if (modId === selectedRef.current) setFeed((prev) => [...prev.slice(-599), item]);
    });
    return off;
  }, []);

  React.useEffect(() => {
    setFeed([]);
    if (!mod) return;
    call("studio:get", { id: mod.id }).then((full) => setFeed(full.feed.slice(-600))).catch(() => {});
  }, [mod?.id]);

  const start = async () => {
    setBusy(true);
    setError("");
    try {
      const created = await call("studio:create", { prompt, seed });
      setSelectedId(created.id);
      setPrompt("");
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const canStart = !busy && !running && (seed || prompt.trim().length >= 8);

  return (
    <div className="build">
      <aside className="build-compose">
        <section className="card compose">
          <label className="field-label" htmlFor="mod-prompt">Describe a mod</label>
          <textarea
            id="mod-prompt"
            className="prompt"
            value={prompt}
            disabled={seed}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="A golden sword that launches mobs into the sky…"
            rows={5}
          />
          <div className="examples">
            {EXAMPLES.map((ex) => (
              <button key={ex} onClick={() => setPrompt(ex)} title={ex} disabled={seed}>
                {ex.split(" ").slice(0, 4).join(" ")}…
              </button>
            ))}
          </div>
          <label className="seed-toggle">
            <input type="checkbox" checked={seed} onChange={(e) => setSeed(e.target.checked)} />
            <span>
              <strong>Use the seeded bug</strong>
              Starts from a labeled buggy fixture. The playtester and fixer still run for real.
            </span>
          </label>
          <button className="btn-primary" disabled={!canStart} onClick={start}>
            {running ? "A mod is running" : busy ? "Starting…" : "Build and playtest"}
          </button>
          {error && <div className="studio-error">{error}</div>}
        </section>

        <section className="card">
          <div className="section-head">
            <h4>Recent mods</h4>
            {mods.length > 0 && <button className="link" onClick={onSeeMods}>See all</button>}
          </div>
          <div className="mod-picks">
            {mods.slice(0, 6).map((m) => (
              <button key={m.id} className={`mod-pick ${m.id === mod?.id ? "active" : ""}`} onClick={() => setSelectedId(m.id)}>
                <span>
                  <strong>{m.name}</strong>
                  <small>
                    {m.attempts.length} attempt{m.attempts.length === 1 ? "" : "s"} · {ago(m.createdAt)} ago
                  </small>
                </span>
                <Pill status={m.status} />
              </button>
            ))}
            {!mods.length && <Empty>No mods yet. Describe one to start.</Empty>}
          </div>
        </section>

        <section className="card lessons">
          <div className="section-head">
            <h4>Learned by the fixer</h4>
            <span className="count">{lessons.length}</span>
          </div>
          {lessons.length ? (
            <ul>
              {lessons.slice(-4).reverse().map((l) => (
                <li key={l.at}>
                  <span>{l.lesson}</span>
                  <small>{l.mod}</small>
                </li>
              ))}
            </ul>
          ) : (
            <Empty>Lessons appear here after a fix passes. Later builders read them first.</Empty>
          )}
        </section>
      </aside>

      <section className="build-stage">
        <Stepper mod={mod} />
        <div className="stage-card">
          <GamePane showLog={false} />
        </div>
        <Feed feed={feed} mod={mod} />
      </section>

      <aside className="build-inspector">
        {mod ? <ModBrief mod={mod} /> : <Empty>Select or describe a mod to see its test plan and attempts.</Empty>}
      </aside>
    </div>
  );
}

function ModBrief({ mod }) {
  return (
    <>
      <div className="brief-head">
        <div>
          <h3>{mod.name}</h3>
          <p className="brief-prompt">“{mod.prompt}”</p>
        </div>
        <Pill status={mod.status} />
      </div>
      {mod.seed && <div className="notice">Seeded bug fallback. Attempt 1 uses a labeled buggy fixture.</div>}
      {mod.running && (
        <button className="btn-danger" onClick={() => call("studio:stop", { id: mod.id })}>
          Stop this run
        </button>
      )}
      {mod.error && <div className="studio-error">{mod.error}</div>}
      <PlanChecks mod={mod} />
      <div className="section-head">
        <h4>Attempts</h4>
        <span className="count">{mod.attempts.length}</span>
      </div>
      <AttemptTimeline mod={mod} />
      <div className="section-head">
        <h4>Partners</h4>
      </div>
      <PartnerStatus mod={mod} />
      {mod.repoDir && (
        <button className="link" onClick={() => call("open-path", mod.repoDir)}>
          Open the mod repository ({shortSha(mod.attempts.at(-1)?.commit?.sha) || "no commit yet"})
        </button>
      )}
    </>
  );
}

function Stepper({ mod }) {
  const current = phaseIndex(mod);
  const done = mod?.status === "passed";
  const failed = ["failed", "stopped"].includes(mod?.status);
  return (
    <ol className="stepper" aria-label="Pipeline">
      {PHASES.map(([key, label], i) => {
        const state =
          i < current || (done && i <= current) ? "done" : i === current && !done ? (failed ? "failed" : "current") : "";
        return (
          <li key={key} className={`step ${state}`}>
            <span className="step-num">{String(i + 1).padStart(2, "0")}</span>
            <span className="step-label">{label}</span>
          </li>
        );
      })}
      {mod && (
        <span className="stepper-meta">
          {mod.attempts.length ? `Attempt ${mod.attempts.length}` : "Not started"}
        </span>
      )}
    </ol>
  );
}

function Feed({ feed, mod }) {
  const ref = React.useRef(null);
  React.useEffect(() => {
    if (ref.current) ref.current.scrollTop = ref.current.scrollHeight;
  }, [feed.length]);
  const visible = feed.filter((f) => f.kind !== "result" || f.isError || f.role === "playtester");
  return (
    <section className="feed" ref={ref}>
      {!visible.length && <Empty>{mod ? "Waiting for agent activity." : "Agent activity appears here."}</Empty>}
      {visible.slice(-250).map((f, i) => (
        <div key={`${f.at}-${i}`} className={`feed-row ${f.role} ${f.kind}`}>
          <span className="feed-role">{ROLE[f.role] || f.role}</span>
          {f.attempt ? <span className="feed-attempt">#{f.attempt}</span> : null}
          <span className="feed-text">
            {f.kind === "tool" ? (
              <>
                <code>{f.name}</code> {f.summary}
              </>
            ) : f.kind === "result" ? (
              <>
                <code>{f.name}</code> → {f.text.slice(0, 300)}
              </>
            ) : (
              f.text
            )}
          </span>
        </div>
      ))}
    </section>
  );
}

import React from "react";
import { call } from "../../api.js";
import { Empty, ROLE, shortSha } from "./shared.jsx";

function groupByDir(paths) {
  const groups = new Map();
  for (const p of paths) {
    const i = p.lastIndexOf("/");
    const dir = i < 0 ? "" : p.slice(0, i);
    if (!groups.has(dir)) groups.set(dir, []);
    groups.get(dir).push(p);
  }
  return [...groups.entries()];
}

function diffKind(line) {
  if (line.startsWith("+++") || line.startsWith("---")) return "meta";
  if (line.startsWith("+")) return "add";
  if (line.startsWith("-")) return "del";
  if (line.startsWith("@@")) return "hunk";
  if (/^(commit |Author:|Date:)/.test(line)) return "meta";
  return "";
}

export default function CodeView({ mod, initialSha }) {
  const commits = React.useMemo(
    () =>
      mod.attempts.flatMap((a) =>
        [
          a.commit?.sha && {
            sha: a.commit.sha,
            title: `Attempt ${a.n} · ${a.role === "seeded" ? "Seeded" : ROLE[a.role]}`,
            failed: a.failure?.kind === "build",
          },
          a.playtestCommit?.sha && { sha: a.playtestCommit.sha, title: `Playtest ${a.n}`, failed: !a.verdict?.passed },
        ].filter(Boolean),
      ),
    [mod],
  );

  const [view, setView] = React.useState(initialSha ? "changes" : "files");
  const [files, setFiles] = React.useState(null);
  const [filesError, setFilesError] = React.useState("");
  const [openPath, setOpenPath] = React.useState(null);
  const [content, setContent] = React.useState("");
  const [sha, setSha] = React.useState(initialSha || commits.at(-1)?.sha || null);
  const [patch, setPatch] = React.useState("");

  React.useEffect(() => {
    setFiles(null);
    setFilesError("");
    if (!mod.repoDir) return;
    call("studio:files", { id: mod.id })
      .then((list) => {
        setFiles(list);
        setOpenPath((cur) => (cur && list.includes(cur) ? cur : list.find((f) => f.endsWith(".java")) || list[0] || null));
      })
      .catch((e) => setFilesError(e.message));
  }, [mod.id, mod.repoDir, mod.attempts.length]);

  React.useEffect(() => {
    if (!openPath) return;
    setContent("");
    call("studio:file", { id: mod.id, path: openPath })
      .then(setContent)
      .catch((e) => setContent(`// ${e.message}`));
  }, [mod.id, openPath, mod.attempts.length]);

  React.useEffect(() => {
    if (initialSha) setSha(initialSha);
  }, [initialSha]);

  React.useEffect(() => {
    if (!sha) return;
    setPatch("");
    call("studio:diff", { id: mod.id, sha })
      .then(setPatch)
      .catch((e) => setPatch(e.message));
  }, [mod.id, sha]);

  if (!mod.repoDir) return <Empty>This mod has no repository yet. Code appears after the repo is created.</Empty>;

  return (
    <div className="code">
      <div className="segmented">
        <button className={view === "files" ? "on" : ""} onClick={() => setView("files")}>
          Files
          <span>{files?.length ?? ""}</span>
        </button>
        <button className={view === "changes" ? "on" : ""} onClick={() => setView("changes")}>
          Changes
          <span>{commits.length}</span>
        </button>
      </div>

      {view === "files" ? (
        <div className="code-split">
          <nav className="file-tree" aria-label="Files">
            {filesError && <div className="studio-error">{filesError}</div>}
            {!files && !filesError && <Empty>Loading files…</Empty>}
            {files &&
              groupByDir(files).map(([dir, list]) => (
                <div key={dir || "root"} className="tree-group">
                  <small>{dir || "/"}</small>
                  {list.map((p) => (
                    <button key={p} className={p === openPath ? "on" : ""} onClick={() => setOpenPath(p)}>
                      {p.slice(p.lastIndexOf("/") + 1)}
                    </button>
                  ))}
                </div>
              ))}
          </nav>
          <div className="viewer">
            <div className="viewer-head mono">{openPath}</div>
            <div className="code-body">
              {content.split("\n").map((line, i) => (
                <div key={i} className="code-line">
                  <span className="ln">{i + 1}</span>
                  <span className="lc">{line || " "}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : (
        <div className="code-split">
          <nav className="file-tree commit-list" aria-label="Commits">
            {commits.map((c) => (
              <button key={c.sha} className={c.sha === sha ? "on" : ""} onClick={() => setSha(c.sha)}>
                <span>{c.title}</span>
                <small className="mono">
                  {shortSha(c.sha)}
                  {c.failed ? " · failed" : ""}
                </small>
              </button>
            ))}
            {!commits.length && <Empty>No commits yet.</Empty>}
          </nav>
          <div className="viewer">
            <div className="viewer-head mono">{sha ? shortSha(sha) : "No commit selected"}</div>
            <div className="code-body">
              {patch.split("\n").map((line, i) => (
                <div key={i} className={`code-line ${diffKind(line)}`}>
                  <span className="lc">{line || " "}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React from "react";
import { fmtTokens } from "../../api.js";
import { Empty, ROLE, allSessions, fmtDuration, fmtMoney, sessionMs } from "./shared.jsx";

const FAILURE = {
  build: "Did not compile",
  load: "Did not load on the server",
  playtest: "Failed in-game checks",
};

const dayKey = (ts) => {
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};

function summarize(mods) {
  const sessions = allSessions(mods);
  const finished = mods.filter((m) => ["passed", "failed"].includes(m.status));
  const passed = mods.filter((m) => m.status === "passed");
  const tokens = sessions.reduce(
    (t, s) => ({
      in: t.in + (s.usage?.inputTokens || 0),
      out: t.out + (s.usage?.outputTokens || 0),
      cacheRead: t.cacheRead + (s.usage?.cacheReadInputTokens || 0),
    }),
    { in: 0, out: 0, cacheRead: 0 },
  );
  const attempts = mods.flatMap((m) => m.attempts);
  const checkpointCommits = attempts.reduce(
    (n, a) => n + (a.commit?.checkpoint ? 1 : 0) + (a.playtestCommit?.checkpoint ? 1 : 0),
    0,
  );
  const failureKinds = {};
  for (const a of attempts) if (a.failure) failureKinds[a.failure.kind] = (failureKinds[a.failure.kind] || 0) + 1;
  const attemptsToPass = {};
  for (const m of passed) attemptsToPass[m.attempts.length] = (attemptsToPass[m.attempts.length] || 0) + 1;

  const byRole = {};
  const byModel = {};
  for (const s of sessions) {
    const r = (byRole[s.role] ||= { sessions: 0, cost: 0, tokens: 0 });
    r.sessions += 1;
    r.cost += s.usage?.costUsd || 0;
    r.tokens += (s.usage?.inputTokens || 0) + (s.usage?.outputTokens || 0);
    const m = (byModel[s.model || "unknown"] ||= { sessions: 0, cost: 0, ms: 0, timed: 0 });
    m.sessions += 1;
    m.cost += s.usage?.costUsd || 0;
    if (sessionMs(s) != null) {
      m.ms += sessionMs(s);
      m.timed += 1;
    }
  }

  const days = [];
  const now = Date.now();
  for (let i = 13; i >= 0; i--) {
    days.push({ key: dayKey(now - i * 86400000), passed: 0, failed: 0, running: 0 });
  }
  const index = new Map(days.map((d, i) => [d.key, i]));
  for (const m of mods) {
    const i = index.get(dayKey(m.createdAt));
    if (i == null) continue;
    if (m.running) days[i].running += 1;
    else if (m.status === "passed") days[i].passed += 1;
    else if (m.status === "failed") days[i].failed += 1;
  }

  return {
    sessions,
    mods: mods.length,
    passed: passed.length,
    finished: finished.length,
    passRate: finished.length ? passed.length / finished.length : null,
    firstTry: passed.filter((m) => m.attempts.length === 1).length,
    avgAttempts: finished.length ? finished.reduce((n, m) => n + m.attempts.length, 0) / finished.length : null,
    spend: sessions.reduce((n, s) => n + (s.usage?.costUsd || 0), 0),
    tokens,
    checkpointCommits,
    linkedSessions: sessions.filter((s) => s.sessionId).length,
    entireMods: mods.filter((m) => m.partners?.entire?.enabled).length,
    neatlogsMods: mods.filter((m) => m.partners?.neatlogs?.enabled).length,
    failureKinds,
    attemptsToPass,
    byRole,
    byModel,
    days,
  };
}

export default function InsightsPage({ mods, lessons }) {
  const s = React.useMemo(() => summarize(mods), [mods]);
  const totalRoleCost = Object.values(s.byRole).reduce((n, r) => n + r.cost, 0) || 1;

  return (
    <div className="insights">
      <section className="stats">
        <Stat label="Mods built" value={s.mods} sub={`${s.passed} passed`} />
        <Stat
          label="Pass rate"
          value={s.passRate == null ? "—" : `${Math.round(s.passRate * 100)}%`}
          sub={`${s.finished} finished`}
          tone="pass"
        />
        <Stat
          label="First-try passes"
          value={s.firstTry}
          sub={s.passed ? `${Math.round((s.firstTry / s.passed) * 100)}% of passes` : "No passes yet"}
        />
        <Stat label="Avg attempts" value={s.avgAttempts == null ? "—" : s.avgAttempts.toFixed(1)} sub="per finished mod" />
        <Stat label="Agent sessions" value={s.sessions.length} sub={`${s.linkedSessions} with a session ID`} />
        <Stat label="Total spend" value={fmtMoney(s.spend)} sub={`${fmtTokens(s.tokens.in + s.tokens.out)} tokens`} />
      </section>

      <section className="card chart-card">
        <div className="section-head">
          <div>
            <h4>Mods per day</h4>
            <p className="muted-line">Last 14 days, colored by outcome</p>
          </div>
          <div className="legend">
            <span className="lg passed">Passed</span>
            <span className="lg failed">Failed</span>
            <span className="lg running">Running</span>
          </div>
        </div>
        <DailyBars days={s.days} />
      </section>

      <div className="insight-grid">
        <section className="card">
          <div className="section-head">
            <h4>Spend by agent role</h4>
          </div>
          <table className="plain-table">
            <thead>
              <tr>
                <th>Role</th>
                <th className="num">Sessions</th>
                <th className="num">Tokens</th>
                <th>Share</th>
                <th className="num">Cost</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(s.byRole)
                .sort((a, b) => b[1].cost - a[1].cost)
                .map(([role, r]) => (
                  <tr key={role}>
                    <td>{ROLE[role] || role}</td>
                    <td className="num">{r.sessions}</td>
                    <td className="num">{fmtTokens(r.tokens)}</td>
                    <td>
                      <span className="meter">
                        <i style={{ width: `${Math.round((r.cost / totalRoleCost) * 100)}%` }} />
                      </span>
                    </td>
                    <td className="num">{fmtMoney(r.cost)}</td>
                  </tr>
                ))}
            </tbody>
          </table>
          {!Object.keys(s.byRole).length && <Empty>Sessions appear here as agents run.</Empty>}
        </section>

        <section className="card">
          <div className="section-head">
            <h4>Models</h4>
          </div>
          <table className="plain-table">
            <thead>
              <tr>
                <th>Model</th>
                <th className="num">Sessions</th>
                <th className="num">Avg time</th>
                <th className="num">Cost</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(s.byModel).map(([model, m]) => (
                <tr key={model}>
                  <td className="mono">{model}</td>
                  <td className="num">{m.sessions}</td>
                  <td className="num">{m.timed ? fmtDuration(m.ms / m.timed) : "—"}</td>
                  <td className="num">{fmtMoney(m.cost)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {!Object.keys(s.byModel).length && <Empty>No model usage yet.</Empty>}
        </section>

        <section className="card">
          <div className="section-head">
            <h4>Why attempts failed</h4>
          </div>
          <Bars
            rows={Object.entries(s.failureKinds).map(([k, n]) => [FAILURE[k] || k, n])}
            empty="No failed attempts yet."
          />
          <div className="section-head">
            <h4>Attempts needed to pass</h4>
          </div>
          <Bars
            rows={[1, 2, 3].map((n) => [`${n} attempt${n === 1 ? "" : "s"}`, s.attemptsToPass[n] || 0])}
            empty="No passing mods yet."
          />
        </section>

        <section className="card">
          <div className="section-head">
            <h4>Partner coverage</h4>
          </div>
          <Coverage label="Entire checkpoints" value={s.checkpointCommits} sub={`${s.entireMods} of ${s.mods} mod repositories`} />
          <Coverage
            label="Neatlogs sessions"
            value={s.linkedSessions}
            sub={`of ${s.sessions.length} sessions · ${s.neatlogsMods} mods traced`}
          />
          <div className="section-head">
            <h4>Lessons the fixer wrote</h4>
            <span className="count">{lessons.length}</span>
          </div>
          {lessons.length ? (
            <ul className="lesson-list">
              {lessons.slice().reverse().map((l) => (
                <li key={l.at}>
                  <span>{l.lesson}</span>
                  <small>{l.mod}</small>
                </li>
              ))}
            </ul>
          ) : (
            <Empty>Lessons appear after a fix passes.</Empty>
          )}
        </section>
      </div>
    </div>
  );
}

function Stat({ label, value, sub, tone }) {
  return (
    <div className={`stat ${tone || ""}`}>
      <span>{label}</span>
      <strong>{value}</strong>
      <small>{sub}</small>
    </div>
  );
}

function DailyBars({ days }) {
  const W = 760;
  const H = 180;
  const max = Math.max(1, ...days.map((d) => d.passed + d.failed + d.running));
  const slot = W / days.length;
  const bar = slot * 0.56;
  return (
    <svg className="daily" viewBox={`0 0 ${W} ${H + 26}`} role="img" aria-label="Mods per day by outcome">
      {[0.25, 0.5, 0.75, 1].map((f) => (
        <line key={f} x1="0" x2={W} y1={H - H * f} y2={H - H * f} className="grid" />
      ))}
      {days.map((d, i) => {
        const x = i * slot + (slot - bar) / 2;
        let y = H;
        return (
          <g key={d.key}>
            {[
              ["passed", d.passed],
              ["failed", d.failed],
              ["running", d.running],
            ].map(([kind, n]) => {
              if (!n) return null;
              const h = (n / max) * H;
              y -= h;
              return <rect key={kind} className={kind} x={x} y={y} width={bar} height={h} rx="3" />;
            })}
            {(i % 2 === 0 || i === days.length - 1) && (
              <text x={x + bar / 2} y={H + 18} textAnchor="middle">
                {d.key.slice(5).replace("-", "/")}
              </text>
            )}
          </g>
        );
      })}
    </svg>
  );
}

function Bars({ rows, empty }) {
  const max = Math.max(1, ...rows.map(([, n]) => n));
  const total = rows.reduce((n, [, v]) => n + v, 0);
  if (!total) return <Empty>{empty}</Empty>;
  return (
    <ul className="hbars">
      {rows.map(([label, n]) => (
        <li key={label}>
          <span>{label}</span>
          <span className="meter">
            <i style={{ width: `${(n / max) * 100}%` }} />
          </span>
          <strong>{n}</strong>
        </li>
      ))}
    </ul>
  );
}

function Coverage({ label, value, sub }) {
  return (
    <div className="coverage">
      <strong>{value}</strong>
      <div>
        <span>{label}</span>
        <small>{sub}</small>
      </div>
    </div>
  );
}

import React from "react";
import { call } from "../../api.js";
import { Empty, ROLE, allSessions, fmtDuration, fmtMoney, sessionMs } from "./shared.jsx";

const CHECK_LIMIT = 25;

export default function NeatlogsPage({ mods, onOpenMod }) {
  const [status, setStatus] = React.useState(null);
  const [evidence, setEvidence] = React.useState({});
  const [selectedKey, setSelectedKey] = React.useState(null);
  const [checking, setChecking] = React.useState(false);
  const sessions = React.useMemo(() => allSessions(mods), [mods]);
  const linked = sessions.filter((s) => s.sessionId);
  const selected = sessions.find((s) => s.key === selectedKey) || null;
  const matched = Object.values(evidence).filter((e) => e?.matched).length;

  React.useEffect(() => {
    call("studio:partners")
      .then((p) => setStatus(p.neatlogs))
      .catch((e) => setStatus({ configured: true, ok: false, error: e.message }));
  }, []);

  const check = React.useCallback(async (session) => {
    if (!session?.sessionId) return;
    try {
      const result = await call("studio:evidence", { sessionId: session.sessionId });
      setEvidence((prev) => ({ ...prev, [session.key]: result }));
    } catch (e) {
      setEvidence((prev) => ({ ...prev, [session.key]: { configured: true, matched: false, traces: [], error: e.message } }));
    }
  }, []);

  React.useEffect(() => {
    if (selected && !evidence[selected.key]) check(selected);
  }, [selected?.key]);

  const checkAll = async () => {
    setChecking(true);
    for (const s of linked.filter((x) => !evidence[x.key]).slice(0, CHECK_LIMIT)) await check(s);
    setChecking(false);
  };

  const ev = selected ? evidence[selected.key] : null;

  return (
    <div className="neatlogs">
      <section className="card connect">
        <div>
          <span className={`status-dot ${status?.ok ? "running" : status?.configured === false ? "off" : status ? "failed" : "offline"}`} />
          <strong>
            {!status
              ? "Checking Neatlogs…"
              : status.configured === false
                ? "Neatlogs is not configured"
                : status.ok
                  ? "Connected to Neatlogs"
                  : "Neatlogs is unreachable"}
          </strong>
        </div>
        <p className="muted-line">
          {status?.configured === false
            ? "Add NEATLOGS_API_KEY and NEATLOGS_PROJECT_ID to .env. Benana then links each session to its trace here."
            : status?.error || "Every builder, playtester, and fixer session is traced by the Neatlogs hooks in its mod repository."}
        </p>
        <button className="btn-ghost" onClick={checkAll} disabled={checking || !linked.length}>
          {checking ? "Checking traces…" : `Check ${Math.min(linked.length, CHECK_LIMIT)} traces`}
        </button>
      </section>

      <section className="stats compact">
        <div className="stat">
          <span>Agent sessions</span>
          <strong>{sessions.length}</strong>
        </div>
        <div className="stat">
          <span>With a session ID</span>
          <strong>{linked.length}</strong>
          <small>Neatlogs can attribute these</small>
        </div>
        <div className="stat pass">
          <span>Trace matched</span>
          <strong>{matched}</strong>
          <small>of {Object.keys(evidence).length} checked</small>
        </div>
      </section>

      <div className="split">
        <section className="card table-card">
          {sessions.length ? (
            <table className="plain-table sessions">
              <thead>
                <tr>
                  <th>Mod</th>
                  <th>Step</th>
                  <th>Role</th>
                  <th>Model</th>
                  <th className="num">Time</th>
                  <th className="num">Cost</th>
                  <th>Trace</th>
                </tr>
              </thead>
              <tbody>
                {sessions.map((s) => {
                  const e = evidence[s.key];
                  return (
                    <tr key={s.key} className={s.key === selectedKey ? "selected" : ""} onClick={() => setSelectedKey(s.key)}>
                      <td>{s.mod.name}</td>
                      <td>{s.attemptN ? `Attempt ${s.attemptN}` : "Spec"}</td>
                      <td>{ROLE[s.role] || s.role}</td>
                      <td className="mono">{s.model}</td>
                      <td className="num">{fmtDuration(sessionMs(s)) || "—"}</td>
                      <td className="num">{fmtMoney(s.usage?.costUsd)}</td>
                      <td>
                        {!s.sessionId ? (
                          <span className="tag off">No session ID</span>
                        ) : e ? (
                          <span className={`tag ${e.matched ? "neatlogs" : "off"}`}>
                            {e.matched ? `${e.traces.length} trace${e.traces.length === 1 ? "" : "s"}` : "No trace"}
                          </span>
                        ) : (
                          <span className="muted-line">Not checked</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          ) : (
            <Empty>Agent sessions appear here after a mod starts building.</Empty>
          )}
        </section>

        <aside className="card detail-card">
          {!selected && <Empty>Select a session to see its trace.</Empty>}
          {selected && (
            <>
              <div className="section-head">
                <div>
                  <h4>{ROLE[selected.role] || selected.role}</h4>
                  <p className="muted-line">
                    {selected.mod.name} · {selected.attemptN ? `attempt ${selected.attemptN}` : "spec"} · {selected.model}
                  </p>
                </div>
                <button className="link" onClick={() => onOpenMod(selected.mod.id)}>
                  Open mod
                </button>
              </div>
              <dl className="facts stacked">
                <div>
                  <dt>Session ID</dt>
                  <dd className="mono">{selected.sessionId || "Not reported"}</dd>
                </div>
                <div>
                  <dt>Outcome</dt>
                  <dd>{selected.ok === false ? selected.error || "Failed" : selected.endedAt ? "Completed" : "Running"}</dd>
                </div>
                <div>
                  <dt>Tokens</dt>
                  <dd>
                    {(selected.usage?.inputTokens || 0).toLocaleString()} in · {(selected.usage?.outputTokens || 0).toLocaleString()} out
                  </dd>
                </div>
              </dl>
              {ev?.error && <div className="studio-error">{ev.error}</div>}
              {ev && !ev.error && <p className="muted-line">{ev.matchReason || (ev.matched ? "Trace matched." : "No trace yet.")}</p>}
              {ev?.traces?.map((t, i) => (
                <div className="trace" key={t.traceId || t.trace_id || i}>
                  <div className="trace-head">
                    <strong>{t.traceName || t.name || "trace"}</strong>
                    {t.durationMs != null && <small>{fmtDuration(t.durationMs)}</small>}
                  </div>
                  <small className="mono">{t.traceId || t.trace_id || t.id}</small>
                  <ol className="spans">
                    {(t.spans || []).slice(0, 25).map((sp, j) => {
                      const failed = sp.status === "error" || sp.status_code === "ERROR";
                      return (
                        <li key={j} className={failed ? "failed" : ""}>
                          <span>{sp.spanName || sp.name || sp.span_name || "span"}</span>
                          {sp.failure && <small>{sp.failure}</small>}
                        </li>
                      );
                    })}
                  </ol>
                </div>
              ))}
            </>
          )}
        </aside>
      </div>
    </div>
  );
}

import React from "react";
import { call, ago } from "../../api.js";
import { Empty, Pill, ROLE, shortSha } from "./shared.jsx";

const pick = (c, ...keys) => keys.map((k) => c?.[k]).find((v) => v != null && v !== "") ?? "";

export default function EntirePage({ mods, setSelectedId }) {
  const repos = mods.filter((m) => m.repoDir);
  const [selectedId, setLocalId] = React.useState(null);
  const mod = repos.find((m) => m.id === selectedId) || repos[0] || null;
  const [cps, setCps] = React.useState(null);

  React.useEffect(() => {
    setCps(null);
    if (!mod) return;
    call("studio:checkpoints", { id: mod.id }).then(setCps).catch((e) => setCps({ ok: false, items: [], error: e.message }));
  }, [mod?.id, mod?.attempts.length]);

  const commits = mod
    ? mod.attempts.flatMap((a) =>
        [
          a.commit?.sha && {
            sha: a.commit.sha,
            checkpoint: a.commit.checkpoint,
            label: `Attempt ${a.n} · ${a.role === "seeded" ? "Seeded" : ROLE[a.role]}`,
            ok: !a.failure || a.failure.kind !== "build",
          },
          a.playtestCommit?.sha && {
            sha: a.playtestCommit.sha,
            checkpoint: a.playtestCommit.checkpoint,
            label: `Playtest ${a.n} · ${a.verdict?.passed ? "pass" : "fail"}`,
            ok: Boolean(a.verdict?.passed),
          },
        ].filter(Boolean),
      )
    : [];
  const linked = commits.filter((c) => c.checkpoint).length;
  const entireOn = repos.some((m) => m.partners?.entire?.enabled);

  if (!repos.length) return <Empty>No mod repositories yet. Each mod gets a git repository with Entire enabled.</Empty>;

  return (
    <div className="entire">
      <section className="card connect">
        <div>
          <span className={`status-dot ${entireOn ? "running" : "failed"}`} />
          <strong>{entireOn ? "Entire is enabled in mod repositories" : "Entire is not set up"}</strong>
        </div>
        <p className="muted-line">
          Each agent commit carries an Entire-Checkpoint trailer. The fixer reads these checkpoints before it changes the plugin.
        </p>
      </section>

      <div className="split">
        <section className="card repo-list">
          <div className="section-head">
            <h4>Mod repositories</h4>
            <span className="count">{repos.length}</span>
          </div>
          {repos.map((m) => (
            <button key={m.id} className={`repo-pick ${m.id === mod?.id ? "active" : ""}`} onClick={() => setLocalId(m.id)}>
              <span>
                <strong>{m.name}</strong>
                <small>
                  {m.attempts.filter((a) => a.commit?.sha).length} commits · {ago(m.createdAt)} ago
                </small>
              </span>
              <span className={`tag ${m.partners?.entire?.enabled ? "entire" : "off"}`}>
                {m.partners?.entire?.enabled ? "Entire" : "Off"}
              </span>
            </button>
          ))}
        </section>

        <section className="card">
          {mod && (
            <>
              <div className="section-head">
                <div>
                  <h4>{mod.name}</h4>
                  <p className="muted-line">
                    {linked} of {commits.length} commits linked to a checkpoint
                  </p>
                </div>
                <div className="head-actions">
                  <Pill status={mod.status} />
                  <button className="btn-ghost" onClick={() => call("open-path", mod.repoDir)}>
                    Open repository
                  </button>
                  <button className="link" onClick={() => setSelectedId(mod.id)}>
                    Build view
                  </button>
                </div>
              </div>

              <h4 className="sub-h">Commit timeline</h4>
              <ol className="commit-timeline">
                {commits.map((c) => (
                  <li key={c.sha} className={c.ok ? "" : "bad"}>
                    <span className="node" />
                    <div>
                      <strong>{c.label}</strong>
                      <div className="chip-row">
                        <span className="chip mono">{shortSha(c.sha)}</span>
                        {c.checkpoint ? (
                          <span className="tag entire mono">{c.checkpoint.slice(0, 12)}</span>
                        ) : (
                          <span className="tag off">No checkpoint</span>
                        )}
                      </div>
                    </div>
                  </li>
                ))}
                {!commits.length && <Empty>Commits appear here as each attempt finishes.</Empty>}
              </ol>

              <h4 className="sub-h">Checkpoints in this repository</h4>
              {!cps && <Empty>Loading checkpoints…</Empty>}
              {cps && !cps.ok && <div className="studio-error">{cps.error || "Entire could not list checkpoints."}</div>}
              {cps?.ok && cps.items.length === 0 && <Empty>No checkpoints yet.</Empty>}
              {cps?.ok && cps.items.length > 0 && (
                <table className="plain-table">
                  <thead>
                    <tr>
                      <th>Checkpoint</th>
                      <th>Message</th>
                      <th>Session</th>
                      <th>Agent</th>
                    </tr>
                  </thead>
                  <tbody>
                    {cps.items.map((c, i) => (
                      <tr key={pick(c, "checkpoint_id", "id") || i}>
                        <td className="mono">{String(pick(c, "checkpoint_id", "checkpointId", "id")).slice(0, 14)}</td>
                        <td>{pick(c, "message", "title", "summary")}</td>
                        <td className="mono">{String(pick(c, "session_id", "sessionId")).slice(0, 14)}</td>
                        <td>{pick(c, "agent")}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </>
          )}
        </section>
      </div>
    </div>
  );
}

