1	// Mod Studio pipeline: prompt -> spec/test plan -> build -> deploy -> playtest -> fix -> retry.
2	// Interface with the game runtime: docs/hackathon/CONTRACTS.md.
3	const fs = require('node:fs');
4	const path = require('node:path');
5	const { appRoot, dataDir } = require('../env.cjs');
6	const game = require('../game/index.cjs');
7	const neatlogs = require('../neatlogs.cjs');
8	const repo = require('./repo.cjs');
9	const prompts = require('./prompts.cjs');
10	const { runClaude, MODELS } = require('./claude.cjs');
11	
12	const MAX_ATTEMPTS = 3;
13	const studioDir = path.join(dataDir, 'studio');
14	const lessonsFile = path.join(studioDir, 'lessons.json');
15	const SEEDED = path.join(appRoot, 'fixtures', 'seeded');
16	
17	const mods = new Map();
18	let active = null; // { modId, stop }
19	let emit = () => {};
20	let log = () => {};
21	
22	const now = () => Date.now();
23	const modFile = (id) => path.join(studioDir, id, 'mod.json');
24	
25	function publicMod(mod) {
26	  const { feed, ...rest } = mod;
27	  return { ...rest, feedCount: feed.length, running: active?.modId === mod.id };
28	}
29	
30	let saveTimers = new Map();
31	function save(mod) {
32	  mod.updatedAt = now();
33	  emit('studio:mod', publicMod(mod));
34	  clearTimeout(saveTimers.get(mod.id));
35	  saveTimers.set(mod.id, setTimeout(() => {
36	    fs.mkdirSync(path.dirname(modFile(mod.id)), { recursive: true });
37	    fs.writeFileSync(modFile(mod.id), JSON.stringify(mod, null, 2));
38	  }, 300));
39	}
40	
41	function load() {
42	  if (!fs.existsSync(studioDir)) return;
43	  for (const id of fs.readdirSync(studioDir)) {
44	    try {
45	      const mod = JSON.parse(fs.readFileSync(modFile(id), 'utf8'));
46	      if (!['passed', 'failed', 'stopped'].includes(mod.status)) mod.status = 'stopped';
47	      mods.set(mod.id, mod);
48	    } catch {}
49	  }
50	}
51	
52	function feed(mod, entry) {
53	  const item = { at: now(), ...entry };
54	  mod.feed.push(item);
55	  if (mod.feed.length > 1500) mod.feed.splice(0, 300);
56	  emit('studio:feed', { modId: mod.id, item });
57	}
58	
59	function setPhase(mod, phase, text) {
60	  mod.phase = phase;
61	  if (text) feed(mod, { role: 'benana', kind: 'phase', phase, text });
62	  save(mod);
63	}
64	
65	function lessons() {
66	  try { return JSON.parse(fs.readFileSync(lessonsFile, 'utf8')); } catch { return []; }
67	}
68	
69	function addLesson(lesson, mod) {
70	  const all = lessons();
71	  all.push({ lesson, mod: mod.name, at: now() });
72	  fs.mkdirSync(studioDir, { recursive: true });
73	  fs.writeFileSync(lessonsFile, JSON.stringify(all.slice(-20), null, 2));
74	}
75	
76	function parseJson(text) {
77	  const fenced = String(text).match(/```(?:json)?\s*([\s\S]*?)```/);
78	  const raw = fenced ? fenced[1] : String(text).slice(String(text).indexOf('{'), String(text).lastIndexOf('}') + 1);
79	  return JSON.parse(raw);
80	}
81	
82	const slugify = (s) => s.replace(/([a-z])([A-Z])/g, '$1-$2').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase().slice(0, 32);
83	
84	// Runs one agent session for a mod and records it on the attempt.
85	async function agent(mod, attempt, role, options) {
86	  const session = { role, model: options.model, startedAt: now(), sessionId: null };
87	  if (attempt) attempt.sessions.push(session);
88	  else mod.sessions.push(session);
89	  save(mod);
90	  const handle = runClaude({
91	    ...options,
92	    onEvent: (ev) => {
93	      if (ev.kind === 'session') { session.sessionId = ev.sessionId; save(mod); return; }
94	      feed(mod, { attempt: attempt?.n ?? 0, role, ...ev, input: undefined });
95	      if (role === 'playtester' && ev.kind === 'tool') emit('studio:playtester', { modId: mod.id, tool: ev.name, input: ev.input });
96	    },
97	  });
98	  active.stop = handle.stop;
99	  const result = await handle.done;
100	  Object.assign(session, { endedAt: now(), ok: result.ok, error: result.error, usage: result.usage, sessionId: result.sessionId || session.sessionId });
101	  save(mod);
102	  if (active?.stopped) throw new Error('Stopped by user.');
103	  return result;
104	}
105	
106	async function specPhase(mod) {
107	  if (mod.seed) {
108	    const seeded = JSON.parse(fs.readFileSync(path.join(SEEDED, 'spec.json'), 'utf8'));
109	    feed(mod, { role: 'benana', kind: 'note', text: 'Seeded bug fallback: using the labeled LaunchSword fixture spec instead of the spec agent.' });
110	    return seeded;
111	  }
112	  const work = path.join(studioDir, mod.id, 'spec');
113	  fs.mkdirSync(work, { recursive: true });
114	  const res = await agent(mod, null, 'spec', { cwd: work, prompt: prompts.spec(mod.prompt), model: MODELS.build, tools: [] });
115	  if (!res.ok) throw new Error(`Spec agent failed: ${res.error}`);
116	  const spec = parseJson(res.final);
117	  if (!/^[A-Za-z]{2,24}$/.test(spec.modName || '')) spec.modName = 'StudioMod';
118	  if (!spec.testPlan?.checks?.length) throw new Error('Spec agent returned no test checks.');
119	  spec.testPlan.modName = spec.modName;
120	  return spec;
121	}
122	
123	async function trace(sessionId) {
124	  if (!sessionId || !neatlogs.configured()) return '';
125	  const ev = await neatlogs.evidence({ sessionId });
126	  if (!ev.matched) return '';
127	  return ev.traces.map((t) => {
128	    const spans = (t.spans || []).slice(0, 25).map((s) => `  - ${s.name || s.span_name || 'span'}${s.status === 'error' || s.status_code === 'ERROR' ? ' (error)' : ''}`).join('\n');
129	    return `trace ${t.traceId || t.trace_id || t.id}\n${spans}`;
130	  }).join('\n').slice(0, 4000);
131	}
132	
133	async function codePhase(mod, attempt, previous) {
134	  if (attempt.role === 'seeded') {
135	    fs.copyFileSync(path.join(SEEDED, 'LaunchSword.java'), path.join(mod.repoDir, 'src', 'main', 'java', 'dev', 'benana', 'mod', 'LaunchSword.java'));
136	    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: 'Seeded bug fallback: attempt 1 uses the labeled fixture source (velocity set inside the damage event).' });
137	    return;
138	  }
139	  const lessonList = lessons().map((l) => l.lesson);
140	  if (attempt.role === 'builder') {
141	    const res = await agent(mod, attempt, 'builder', { cwd: mod.repoDir, prompt: prompts.builder({ mod, lessons: lessonList }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
142	    if (!res.ok) throw new Error(`Builder failed: ${res.error}`);
143	    attempt.summary = res.final.slice(0, 2000);
144	    return;
145	  }
146	  const cps = await repo.checkpoints(mod.repoDir);
147	  const context = {
148	    history: await repo.history(mod.repoDir),
149	    checkpoints: cps.ok ? cps.items.slice(0, 8).map((c) => `${c.checkpoint_id} "${c.message}" session ${c.session_id} (${c.agent})`).join('\n') : '',
150	    trace: await trace(previous.sessions.find((s) => s.role === 'playtester')?.sessionId).catch(() => ''),
151	  };
152	  attempt.context = { entireCheckpoints: cps.ok ? cps.items.length : 0, neatlogsTrace: Boolean(context.trace) };
153	  const res = await agent(mod, attempt, 'fixer', { cwd: mod.repoDir, prompt: prompts.fixer({ mod, attempt, previous, context }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
154	  if (!res.ok) throw new Error(`Fixer failed: ${res.error}`);
155	  attempt.summary = res.final.slice(0, 2000);
156	  const lesson = res.final.match(/^LESSON:\s*(.+)$/m);
157	  if (lesson) attempt.lesson = lesson[1].trim();
158	}
159	
160	async function playtestPhase(mod, attempt) {
161	  const dir = path.join(mod.repoDir, 'playtest', `attempt-${attempt.n}`);
162	  fs.mkdirSync(dir, { recursive: true });
163	  const verdictFile = path.join(dir, 'verdict.json');
164	  const testPlanFile = path.join(mod.repoDir, 'playtest', 'test-plan.json');
165	  fs.rmSync(verdictFile, { force: true });
166	
167	  if (game.status().mock) {
168	    const v = game.mockVerdict(mod.testPlan, attempt.n);
169	    fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
170	    feed(mod, { attempt: attempt.n, role: 'playtester', kind: 'note', text: '[mock runtime] canned verdict' });
171	    return game.readVerdict(verdictFile);
172	  }
173	
174	  for (let run = 1; run <= 2; run++) {
175	    const mcpFile = path.join(studioDir, mod.id, `mcp-attempt-${attempt.n}.json`);
176	    fs.mkdirSync(path.dirname(mcpFile), { recursive: true });
177	    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId: `${mod.id}_${attempt.n}`, verdictFile, testPlanFile })));
178	    const poll = setInterval(() => {
179	      if (!fs.existsSync(verdictFile)) return;
180	      const live = game.readVerdict(verdictFile);
181	      attempt.verdict = { ...live, live: true };
182	      save(mod);
183	    }, 1000);
184	    try {
185	      await agent(mod, attempt, 'playtester', { cwd: mod.repoDir, prompt: game.playtestPrompt(mod.testPlan), model: MODELS.playtest, tools: [], allowedTools: game.playtesterTools, mcpConfigFile: mcpFile });
186	    } finally {
187	      clearInterval(poll);
188	    }
189	    const verdict = game.readVerdict(verdictFile);
190	    if (verdict.finished) return verdict;
191	    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: run === 1 ? 'The playtester stopped before finishing; running it again.' : 'The playtester did not finish the test plan.' });
192	  }
193	  return game.readVerdict(verdictFile);
194	}
195	
196	async function runAttempt(mod, n, previous) {
197	  const attempt = { n, role: n === 1 ? (mod.seed ? 'seeded' : 'builder') : 'fixer', status: 'running', startedAt: now(), sessions: [] };
198	  mod.attempts.push(attempt);
199	  save(mod);
200	
201	  setPhase(mod, n === 1 ? 'build' : 'fix', n === 1 ? `Attempt 1: writing ${mod.name}` : `Attempt ${n}: fixing what the playtester found`);
202	  await codePhase(mod, attempt, previous);
203	
204	  setPhase(mod, 'compile', `Attempt ${n}: compiling with Maven`);
205	  attempt.build = await repo.build(mod.repoDir, mod.name);
206	  if (!attempt.build.ok) {
207	    attempt.failure = { kind: 'build', summary: 'The plugin did not compile.' };
208	    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): build failed`);
209	    return attempt;
210	  }
211	  attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): ${attempt.role === 'fixer' ? 'fix from playtest evidence' : 'implement'} ${mod.name}`);
212	  feed(mod, { attempt: n, role: 'benana', kind: 'note', text: `Committed ${attempt.commit.sha.slice(0, 7)}${attempt.commit.checkpoint ? `, Entire checkpoint ${attempt.commit.checkpoint}` : ''}` });
213	
214	  setPhase(mod, 'deploy', `Attempt ${n}: deploying to the Paper server`);
215	  attempt.deploy = await game.deployPlugin({ jarPath: attempt.build.jar, emit });
216	  if (!attempt.deploy.loaded) {
217	    attempt.failure = { kind: 'load', summary: 'The plugin did not load on the server.' };
218	    return attempt;
219	  }
220	
221	  setPhase(mod, 'playtest', `Attempt ${n}: the AI player is testing ${mod.name} in-game`);
222	  attempt.verdict = await playtestPhase(mod, attempt);
223	  const tally = attempt.verdict.checks.map((c) => `${c.id}=${c.status}`).join(', ');
224	  attempt.playtestCommit = await repo.commit(mod.repoDir, `Playtest attempt ${n}: ${attempt.verdict.passed ? 'PASS' : 'FAIL'}${tally ? ` (${tally})` : ''}`);
225	  if (!attempt.verdict.passed) {
226	    const failed = attempt.verdict.checks.filter((c) => c.status !== 'pass');
227	    attempt.failure = attempt.verdict.finished
228	      ? { kind: 'playtest', summary: failed.length ? failed.map((c) => `${c.id}: ${c.observed}`).join(' · ') : `${attempt.verdict.serverErrors.length} server error(s)` }
229	      : { kind: 'playtest', summary: attempt.verdict.error || 'The playtester did not finish.' };
230	  }
231	  return attempt;
232	}
233	
234	async function run(mod) {
235	  active = { modId: mod.id, stop: () => {}, stopped: false };
236	  try {
237	    if (game.status().bot !== 'online' && !game.status().mock) {
238	      setPhase(mod, 'game', 'Starting the Minecraft server');
239	      await game.start(emit);
240	    }
241	    mod.status = 'running';
242	    setPhase(mod, 'spec', 'Writing the spec and an in-game test plan');
243	    const spec = await specPhase(mod);
244	    mod.name = spec.modName;
245	    mod.spec = { summary: spec.summary, behavior: spec.behavior || [] };
246	    mod.testPlan = spec.testPlan;
247	    feed(mod, { role: 'spec', kind: 'plan', text: `${mod.testPlan.checks.length} checks: ${mod.testPlan.checks.map((c) => c.title).join(' · ')}` });
248	
249	    setPhase(mod, 'repo', 'Creating the mod repository with Entire and Neatlogs hooks');
250	    const created = await repo.create({ slug: `${slugify(mod.name)}-${mod.id.slice(-4)}`, name: mod.name, summary: mod.spec.summary });
251	    mod.repoDir = created.dir;
252	    mod.partners = created.partners;
253	    fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
254	    fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
255	    await repo.commit(mod.repoDir, 'Add the in-game test plan');
256	    save(mod);
257	
258	    let previous = null;
259	    for (let n = 1; n <= MAX_ATTEMPTS; n++) {
260	      const attempt = await runAttempt(mod, n, previous);
261	      attempt.status = attempt.failure ? 'failed' : 'passed';
262	      attempt.endedAt = now();
263	      save(mod);
264	      if (!attempt.failure) {
265	        mod.status = 'passed';
266	        if (attempt.lesson) addLesson(attempt.lesson, mod);
267	        setPhase(mod, 'done', n === 1 ? `${mod.name} passed every check on the first attempt` : `${mod.name} passed after ${n} attempts`);
268	        return;
269	      }
270	      feed(mod, { attempt: n, role: 'benana', kind: 'failure', text: `Attempt ${n} failed (${attempt.failure.kind}): ${attempt.failure.summary}` });
271	      previous = attempt;
272	    }
273	    mod.status = 'failed';
274	    setPhase(mod, 'done', `${mod.name} still fails after ${MAX_ATTEMPTS} attempts`);
275	  } catch (e) {
276	    mod.status = active?.stopped ? 'stopped' : 'failed';
277	    mod.error = e.message;
278	    feed(mod, { role: 'benana', kind: 'error', text: e.message });
279	    log(`studio: ${e.message}`, 'error');
280	    save(mod);
281	  } finally {
282	    active = null;
283	    save(mod);
284	  }
285	}
286	
287	function create({ prompt, seed = false }) {
288	  if (active) throw new Error('Another mod is running. Stop it or wait for it to finish.');
289	  const text = String(prompt || '').trim();
290	  if (!seed && text.length < 8) throw new Error('Describe the mod in a sentence.');
291	  const id = `mod_${now().toString(36)}`;
292	  const mod = {
293	    id, prompt: seed ? text || 'A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.' : text,
294	    seed: Boolean(seed), name: 'New mod', status: 'queued', phase: 'queued', createdAt: now(), updatedAt: now(),
295	    spec: null, testPlan: null, repoDir: null, partners: null, sessions: [], attempts: [], feed: [], error: null,
296	  };
297	  mods.set(id, mod);
298	  save(mod);
299	  run(mod);
300	  return publicMod(mod);
301	}
302	
303	function repoOf(id) {
304	  const mod = mods.get(id);
305	  if (!mod?.repoDir) throw new Error('This mod has no repository yet.');
306	  return mod.repoDir;
307	}
308	
309	function handlers(deps) {
310	  emit = deps.emit;
311	  log = deps.log;
312	  load();
313	  return {
314	    'studio:list': () => [...mods.values()].sort((a, b) => b.createdAt - a.createdAt).map(publicMod),
315	    'studio:get': ({ id }) => {
316	      const mod = mods.get(id);
317	      if (!mod) throw new Error('Unknown mod.');
318	      return { ...publicMod(mod), feed: mod.feed };
319	    },
320	    'studio:create': create,
321	    'studio:stop': ({ id }) => {
322	      if (active?.modId !== id) return false;
323	      active.stopped = true;
324	      active.stop();
325	      return true;
326	    },
327	    'studio:evidence': ({ sessionId }) => neatlogs.evidence({ sessionId }),
328	    'studio:checkpoints': async ({ id }) => {
329	      const mod = mods.get(id);
330	      return mod?.repoDir ? repo.checkpoints(mod.repoDir) : { ok: false, items: [], error: 'No repository yet.' };
331	    },
332	    'studio:files': ({ id }) => repo.files(repoOf(id)),
333	    'studio:file': ({ id, path: rel }) => repo.readFile(repoOf(id), rel),
334	    'studio:diff': ({ id, sha }) => repo.diff(repoOf(id), sha),
335	    'studio:lessons': () => lessons(),
336	    'studio:partners': async () => ({ neatlogs: await neatlogs.status() }),
337	  };
338	}
339	
340	module.exports = { handlers };
341

input.content:
.game-pane {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  gap: 10px;
}
.game-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #949ba3;
}
.game-bar strong {
  margin-right: 8px;
  font-family: Bahnschrift, "Segoe UI Semibold", system-ui, sans-serif;
  font-weight: 600;
  color: #ece9e2;
}
.game-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #626a72;
}
.game-dot.starting,
.game-dot.connecting {
  background: #f2b544;
}
.game-dot.running,
.game-dot.online {
  background: #7fcf5a;
}
.game-dot.error {
  background: #ec6a5b;
}
.game-tag {
  padding: 2px 7px;
  border-radius: 5px;
  background: rgba(242, 181, 68, 0.14);
  color: #f2b544;
  font-size: 10.5px;
  font-weight: 600;
}
.game-btn {
  margin-left: auto;
  padding: 7px 14px;
  border: 0;
  border-radius: 9px;
  background: #f2b544;
  color: #1a1408;
  font-weight: 600;
  cursor: pointer;
}
.game-btn.ghost {
  background: #1d2226;
  border: 1px solid #373f46;
  color: #ece9e2;
  font-weight: 500;
}
.game-btn.ghost + .game-btn {
  margin-left: 0;
}
.game-btn:hover:not(:disabled) {
  filter: brightness(1.08);
}
.game-btn:disabled {
  opacity: 0.45;
  cursor: default;
}
.game-view {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 1px solid #2a3035;
  border-radius: 12px;
  overflow: hidden;
  background: #0b0d0f;
}
.game-view iframe {
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
.game-empty {
  display: grid;
  place-items: center;
  height: 100%;
  color: #626a72;
  font-size: 13px;
}
.game-actions {
  position: absolute;
  left: 12px;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.game-action.error code {
  color: #f5a196;
}
.game-action {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 6px 10px;
  border-radius: 7px;
  background: rgba(12, 14, 16, 0.85);
  border: 1px solid #2a3035;
  color: #ece9e2;
  font-size: 12px;
}
.game-action code {
  color: #7fcf5a;
  font-family: "Cascadia Mono", Consolas, monospace;
  font-size: 11px;
}
.game-error {
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(236, 106, 91, 0.12);
  color: #f5a196;
  font-size: 12px;
}
.game-log {
  margin: 0;
  height: 120px;
  padding: 8px 10px;
  overflow: auto;
  border: 1px solid #2a3035;
  border-radius: 8px;
  background: #0c0e10;
  color: #cfcac0;
  font-family: "Cascadia Mono", Consolas, monospace;
  font-size: 11px;
  white-space: pre-wrap;
}

const NOW = Date.now();
const MIN = 60_000;
const OPUS = "claude-opus-5-5";
const SONNET = "claude-sonnet-5-5";
const at = (agoMin) => NOW - agoMin * MIN;

const check = (id, title, expect) => ({ id, title, expect });
const vcheck = (id, status, observed) => ({ id, status, observed });
const verdict = ({ passed, finished = true, checks, live = false, error = null }) => ({
  passed,
  finished,
  checks,
  live,
  error,
  serverErrors: [],
});
const commit = (sha, checkpoint = null) => ({ sha, checkpoint });

const session = ({ role, model = OPUS, startAgo, lenMin = null, sessionId, cost, inTok, outTok, ok = true, error = null }) => ({
  role,
  model,
  sessionId,
  startedAt: at(startAgo),
  endedAt: lenMin == null ? null : at(startAgo - lenMin),
  ok: lenMin == null ? undefined : ok,
  error,
  usage: {
    inputTokens: inTok,
    outputTokens: outTok,
    cacheReadInputTokens: Math.round(inTok * 0.6),
    cacheCreationInputTokens: 0,
    costUsd: cost,
  },
});

const attempt = ({
  n,
  role,
  status,
  startAgo,
  sessions,
  build = { ok: true },
  deploy = null,
  commit: c,
  playtestCommit = null,
